    from flowguard.map.impact import compute_impact
    h=literal_fixture();data=h['fixture'](tmp_path)
    h['write'](tmp_path,'consumer.py','def use(value):\n    raise ValueError("an item is missing")\n')
    impact=compute_impact(tmp_path,data,build_inventory(tmp_path,DEFAULT_IGNORE,write_cache=False),['consumer.py'],base='HEAD')
    # The real deleted interface token still names a producer; ordinary text does not.
    assert not any('an item is missing' in line for line in impact.consumer_lines)
    path=tmp_path/'consumer.py';before=path.read_text()
    subprocess.run(['git','-C',str(tmp_path),'add','.'],check=True)
    subprocess.run(['git','-C',str(tmp_path),'-c','user.name=FlowGuard','-c','user.email=model@example.invalid','commit','-qm','message baseline'],check=True,capture_output=True)
    path.write_text(before.replace('an item is missing','a different item is missing'))
    result=compute_impact(tmp_path,data,build_inventory(tmp_path,DEFAULT_IGNORE,write_cache=False),['consumer.py'],base='HEAD')
    assert result.consumer_lines==[]


